from itertools import permutations

class Solution:
    def reformat(self, s: str) -> str:
        for p in set(permutations(s)):
            ok = all(p[i].isalpha() != p[i+1].isalpha() for i in range(len(p)-1))
            if ok:
                return ''.join(p)
        return ""

