class Solution {
public:
    bool valid(const string& p) {
        for (int i = 0; i + 1 < (int)p.size(); i++)
            if (isdigit(p[i]) == isdigit(p[i+1])) return false;
        return true;
    }
    void go(string& s, int i, string& ans) {
        if (!ans.empty()) return;
        if (i == (int)s.size()) { if (valid(s)) ans = s; return; }
        for (int j = i; j < (int)s.size(); j++) {
            swap(s[i], s[j]);
            go(s, i + 1, ans);
            swap(s[i], s[j]);
        }
    }
    string reformat(string s) {
        string ans = "";
        go(s, 0, ans);
        return ans;
    }
};

