class Solution {
    private String ans = "";

    private boolean valid(char[] p) {
        for (int i = 0; i + 1 < p.length; i++)
            if (Character.isDigit(p[i]) == Character.isDigit(p[i+1])) return false;
        return true;
    }

    private void go(char[] s, int i) {
        if (!ans.isEmpty()) return;
        if (i == s.length) { if (valid(s)) ans = new String(s); return; }
        for (int j = i; j < s.length; j++) {
            char t = s[i]; s[i] = s[j]; s[j] = t;
            go(s, i + 1);
            t = s[i]; s[i] = s[j]; s[j] = t;
        }
    }

    public String reformat(String s) {
        go(s.toCharArray(), 0);
        return ans;
    }
}

