    const arr = s.split('');
    let ans = '';
    const valid = p => {
        for (let i = 0; i + 1 < p.length; i++)
            if (/\d/.test(p[i]) === /\d/.test(p[i+1])) return false;
        return true;
    };
    const go = i => {
        if (ans !== '') return;
        if (i === arr.length) { if (valid(arr)) ans = arr.join(''); return; }
        for (let j = i; j < arr.length; j++) {
            [arr[i], arr[j]] = [arr[j], arr[i]];
            go(i + 1);
            [arr[i], arr[j]] = [arr[j], arr[i]];
        }
    };
    go(0);
    return ans;
};

