class Solution {
public:
    string reformat(string s) {
        vector<char> letters, digits;
        for (char c : s) (isdigit(c) ? digits : letters).push_back(c);
        if (abs((int)letters.size() - (int)digits.size()) > 1) return "";
        if (letters.size() < digits.size()) swap(letters, digits);
        int n = s.size();
        string res(n, ' ');
        int li = 0, di = 0;
        for (int i = 0; i < n; i++)
            res[i] = (i % 2 == 0) ? letters[li++] : digits[di++];
        return res;
    }
};

