class Solution {
    public String reformat(String s) {
        StringBuilder L = new StringBuilder(), D = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) D.append(c); else L.append(c);
        }
        if (Math.abs(L.length() - D.length()) > 1) return "";
        if (L.length() < D.length()) {
            StringBuilder t = L; L = D; D = t;
        }
        char[] res = new char[s.length()];
        int li = 0, di = 0;
        for (int i = 0; i < s.length(); i++)
            res[i] = (i % 2 == 0) ? L.charAt(li++) : D.charAt(di++);
        return new String(res);
    }
}

